// IsFullCube reports whether a state's collision shape is the whole block —
// per STATE: a double slab is, a single slab is not; a retracted piston base
// is, an extended one is not.
func IsFullCube(state uint32) bool {
	lo, hi := 0, len(fullCubeRanges)-1
	for lo <= hi {
		mid := (lo + hi) / 2
		r := fullCubeRanges[mid]
		switch {
		case state < r.Min:
			hi = mid - 1
		case state > r.Max:
			lo = mid + 1
		default:
			return true
		}
	}
	return false
}
